    E = N * (N - 1) // 2

    comb = [[0] * (E + 1) for _ in range(E + 1)]
    for i in range(E + 1):
        comb[i][0] = comb[i][i] = 1
        if i:
            prev = comb[i - 1]
            row = comb[i]
            for j in range(1, i):
                row[j] = (prev[j - 1] + prev[j]) % P

    fact = [1] * (N + 1)
    invfact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % P
    invfact[N] = pow(fact[N], P - 2, P)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % P

    trans = [[None] * (H + 1) for _ in range(H + 1)]
    for a in range(1, H + 1):
        for b in range(1, H + 1):
            poly = [0] * (a * b + 1)

            # ((1+x)^a - 1)^b
            for j in range(b + 1):
                coef = comb[b][j]
                if (b - j) & 1:
                    coef = P - coef
                row = comb[a * j]
                for d in range(a * j + 1):
                    poly[d] = (poly[d] + coef * row[d]) % P

            # Multiply by (1+x)^(b choose 2), for edges inside the new layer.
            inside = b * (b - 1) // 2
            res = [0] * (a * b + inside + 1)
            row_inside = comb[inside]
            for d, val in enumerate(poly):
