                        res[d + r] = (res[d + r] + val * row_inside[r]) % P

            scale = invfact[b]
            for i in range(len(res)):
                res[i] = res[i] * scale % P

            trans[a][b] = (b, res[b:], len(res) - 1)

    layers = [dict() for _ in range(N + 1)]
    start = [0] * (E + 1)
    start[0] = 1
    layers[1][(1, 0, 1, 0)] = [start, 0, 0]  # even_count, odd_count, last_size, parity

    for used in range(1, N):
        for (even, odd, last, parity), (src, lo, hi) in list(layers[used].items()):
            next_parity = 1 - parity
            remaining = H - (odd if next_parity else even)

            for b in range(1, remaining + 1):
                neven = even + (b if next_parity == 0 else 0)
                nodd = odd + (b if next_parity == 1 else 0)
                nused = used + b
                key = (neven, nodd, b, next_parity)

                item = layers[nused].get(key)
                if item is None:
                    item = [[0] * (E + 1), E + 1, -1]
                    layers[nused][key] = item

                dest = item[0]
                tlo, tcoef, thi = trans[last][b]

                for i in range(lo, hi + 1):
                    sv = src[i]
                    if sv:
                        pos = i + tlo
                        for tv in tcoef:
                            dest[pos] += sv * tv
                            pos += 1

                nlo = lo + tlo
                nhi = hi + thi
                for i in range(nlo, nhi + 1):
                    dest[i] %= P

                if nlo < item[1]:
                    item[1] = nlo
                if nhi > item[2]:
                    item[2] = nhi

    ans = [0] * (E + 1)
    for poly, lo, hi in layers[N].values():
        for m in range(lo, hi + 1):
            ans[m] = (ans[m] + poly[m]) % P

    label_factor = fact[N - 1]
    print(" ".join(str(ans[m] * label_factor % P) for m in range(N - 1, E + 1)))

